    """Return True if brackets in *s* are balanced.
    Only the characters '()', '[]', '{}' are considered; all other characters are ignored.
    """
    opening = set('([{')
    matching = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
