def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses O(n^2) dynamic programming which is simple and reliable for the test sizes.
    """
    if not nums:
        return 0
    n = len(nums)
    dp = [1] * n  # dp[i] = length of LIS ending at i
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)

