def solve(tokens):
    """Evaluate an expression given in Reverse Polish Notation.
    Supports the operators +, -, *, /. Division truncates toward zero as specified.
    """
    stack = []
    for t in tokens:
        if t in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if t == "+":
                res = a + b
            elif t == "-":
                res = a - b
            elif t == "*":
                res = a * b
            else:  # division, truncate toward zero
                # Using int(a / b) achieves truncation toward zero in Python
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    # If the expression is empty, return 0 (though per spec this shouldn't happen)
    return stack[0] if stack else 0

