def solve(grid):
    """Return the number of islands in a 2D grid.
    An island is a group of adjacent 1's (connected vertically or horizontally).
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False] * cols for _ in range(rows)]
    def bfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            i, j = stack.pop()
            for di, dj in ((1,0), (-1,0), (0,1), (0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < cols and not visited[ni][nj] and grid[ni][nj] == 1:
                    visited[ni][nj] = True
                    stack.append((ni, nj))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j] == 1:
                islands += 1
                bfs(i, j)
    return islands

