def solve(s):
    """Return True if the brackets in *s* are balanced.
    Handles any input by returning False for non‑string values.
    """
    if not isinstance(s, str):
        return False
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

