def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division truncates toward zero as in the original problem.
    """
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[0]

